@startuml

enum Interval {
  Weekly
  Monthly
  EveryHalfYear
  Yearly
}

class Person {
  + HealthNumber : string
  + FirstName : string
  + LastName : string
  + Address : string
  + PhoneNumber : string
}

class Doctor extends Person {
  + PractitionerNumber : int
  + Signature : string
}

class Patient extends Person {
  + DateOfBirth : date
}

class Requisition {
  + ValidFromDate : date
  + RepetitionCount : int
  + RepetitionInterval : Interval
}

class Test {
  + Duration : string
  + Result : boolean
  + Report : string
}

class Appointment {
  + ConfirmationNumber : string
  + Date : date
  + StartTime : time
  + EndTime : time
}

class Lab {
  + RegistrationNumber : string
  + Name : string
  + Address : string
  + BusinessHours : string
  + ChangeCancelFee : boolean
}

class BusinessHour {
  + DayOfWeek : string
  + StartTime : time
  + EndTime : time
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : has
Doctor "1" -- "*" Test : views
Patient "1" -- "*" Test : views
Requisition "1" *-- "*" Test : contains
Patient "1" -- "*" Appointment : makes
Appointment "1" -- "1" Lab : at
Lab "1" -- "*" BusinessHour : has
Lab "1" -- "*" Appointment : hosts

@enduml

